using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using EternalSteam.OpenWorld;
public static class FixHud08MenuReferences{public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var m=h.Sandbox.PauseMenu;m.Content=m.Panel.GetComponent<CanvasGroup>();if(m.Content==null)m.Content=m.Panel.gameObject.AddComponent<CanvasGroup>();if(m.Content==null)throw new Exception("Content group authoring failed");h.Sections.Single(s=>s.Id=="developer").Body.SetActive(true);m.Developer=h.Sections.Single(s=>s.Id=="developer-body").Body;m.Developer.SetActive(false);m.Scroll=m.Panel.GetComponentInChildren<UnityEngine.UI.ScrollRect>(true);m.SaveSection=(RectTransform)h.Sections.Single(s=>s.Id=="save-controls").Body.transform;m.ProgressSection=(RectTransform)h.Sections.Single(s=>s.Id=="map-progress").Body.transform;m.DeveloperEntry=(RectTransform)h.Buttons.Single(b=>b.Id=="developer-fold").View.transform;EditorUtility.SetDirty(m);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");scene=EditorSceneManager.OpenScene(scene.path);if(UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>().Sandbox.PauseMenu.Content==null)throw new Exception("Content reference missing after reopen");}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Developer panel reference repaired in both saved scenes";}}
